#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include "animation.h"

Adafruit_SSD1306 display(128, 64, &Wire, -1);

const int frameDelay = 1000 / TARGET_FPS; 

unsigned long lastTime = 0;
int currentFrame = 0;

void setup() {
  // На ESP32 иногда нужно явно указать пины: Wire.begin(21, 22);
  if(!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    for(;;);
  }
  display.clearDisplay();
}

void loop() {
  // Проверяем время (42 мс = ~24 кадра в секунду)
  if (millis() - lastTime >= frameDelay) {
    lastTime = millis();

    display.clearDisplay();
    // Рисуем текущий кадр из нашего файла .h
    // (const uint8_t*) — важная подсказка для ESP32 при чтении из памяти
    display.drawXBitmap(0, 0, (const uint8_t*)oled_frames[currentFrame], 128, 64, WHITE);
    display.display();

    currentFrame++;
    if (currentFrame >= OLED_FRAMES_FRAMES) {
      currentFrame = 0; // Зацикливаем
    }
  }
}
